// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 actorKey, uint256 blockNumber, uint256 timeIncrement) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(actorKey)))));
        vm.assume(actor != address(0));
        vm.assume(blockNumber > 0);
        vm.assume(timeIncrement > 0);

        vm.roll(blockNumber);
        vm.warp(block.timestamp + timeIncrement);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        if (block.number % 15 == 0) {
            assertEq(address(c).balance, 0, "balance must be 0 when block.number % 15 == 0");
        }
    }
}
